select case when quantity >= 247 then 'high' when quantity >= 119 then 'mid' else 'low' end as quantity_bucket, year(last_restock) as last_restock_year, count(quantity) as quantity_count from inventory where quantity = 109 group by case when quantity >= 247 then 'high' when quantity >= 119 then 'mid' else 'low' end, year(last_restock) order by quantity_bucket, last_restock_year limit 20;
